canonical_mapping<-function(catalog,uniprot,ncbi){rows<-list();for(i in seq_len(nrow(catalog))){r<-catalog[i,,drop=FALSE];u<-unique(uniprot[uniprot$source_id%in%as.character(r$uniprot_accession),c("source_id","Reactome_ID","Pathway")]);n<-unique(ncbi[ncbi$source_id%in%as.character(r$ncbi_gene_id),c("source_id","Reactome_ID","Pathway")]);x<-if(nrow(u))u else n;route<-if(nrow(u))"UniProt"else if(nrow(n))"NCBI Gene ID"else"none";if(!nrow(x))x<-data.frame(source_id=NA,Reactome_ID=NA,Pathway=NA);for(j in seq_len(nrow(x)))rows[[length(rows)+1]]<-data.frame(source_row=r$source_row,original_id=r$original_id,reactome_entity_key=if(route=="UniProt")paste0("UP:",x$source_id[j])else if(route!="none")paste0("NCBI:",x$source_id[j])else NA,uniprot_accession=r$uniprot_accession,ncbi_gene_id=r$ncbi_gene_id,gene_symbol=r$gene_symbol,Reactome_ID=x$Reactome_ID[j],Pathway=x$Pathway[j],mapping_route=route,mapping_status=if(route=="none")"unmapped"else"mapped")};do.call(rbind,rows)}
reactome_frequency<-function(mapping,total){pairs<-unique(mapping[!is.na(mapping$reactome_entity_key),c("reactome_entity_key","Reactome_ID","Pathway")]);out<-aggregate(reactome_entity_key~Reactome_ID+Pathway,pairs,function(x)length(unique(x)));names(out)[3]<-"Protein_count";out$Protein_fraction<-out$Protein_count/total;out}
reactome_enrichment<-function(target,background){terms<-unique(background[,c("Reactome_ID","Pathway")]);rows<-lapply(seq_len(nrow(terms)),function(i){id<-terms$Reactome_ID[i];t<-unique(target$reactome_entity_key[target$Reactome_ID==id]);b<-unique(background$reactome_entity_key[background$Reactome_ID==id]);data.frame(Reactome_ID=id,Pathway=terms$Pathway[i],Target_count=length(t),Target_size=length(unique(target$reactome_entity_key)),Background_count=length(b),Background_size=length(unique(background$reactome_entity_key)),p_value=phyper(length(t)-1,length(b),length(unique(background$reactome_entity_key))-length(b),length(unique(target$reactome_entity_key)),lower.tail=FALSE))});o<-do.call(rbind,rows);o$FDR<-p.adjust(o$p_value,"BH");o}
